"""Synthetic valid 640x480 JPEG frame generator for testing and simulation."""

import base64
import functools

FIXTURE_JPEG_B64 = ""


@functools.lru_cache(maxsize=1)
def get_synthetic_jpeg_frame() -> bytes:
    """Return a valid 640x480 baseline JPEG frame as raw bytes."""
    return base64.b64decode(FIXTURE_JPEG_B64)
